INSERT INTO blog_seo (slug, title, description, image_url, page_type) VALUES ('ev-charging-vat', 'EV Charging VAT: Rates, Rules & Compliance | NetworkCore', 'EV charging VAT rates, collection rules, and compliance requirements across Europe, Latin America, North America, and Asia. Why automated VAT handling is essential for cross-border EV charging.', '/images/blog/ev-charging-vat.jpg', 'blog') ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, image_url = EXCLUDED.image_url;